import { useEffect, useState } from "react";
import "./App.css";

import Category from "./components/category/Category";
import Header from "./components/Header";
import { Tab, Tabs, Box, ToggleButtonGroup, ToggleButton } from "@mui/material";
import Items from "./components/Items/Items";
import { useDataStateContext } from "./components/context/DataStateContext";
import { useFireBase } from "./context/FirebaseConfigContext";
import Auth from "./components/Auth/Auth";
import UserHeader from "./components/UserHeader";
import { userConfig, myUsers } from "./config/userConfig";
import { motion, AnimatePresence } from "framer-motion";
import ThemeSwitcher from "./components/ThemeSwitcher";
import OccasionDoodle from "./components/Auth/doodles/OccasionDoodle";
import DoodleField from "./components/PageDoodles/DoodleField";
import { useThemeSwitcher } from "./context/ThemeSwitcherContext";

const UNLOCKED_USER_KEY = "dream_unlocked_user";

function App() {
  const [value, setValue] = useState(0);
  const { state } = useDataStateContext();
  const { state: firebaseState, dispatch: firebaseDispatch } = useFireBase();
  const { themeKey } = useThemeSwitcher();

  const [alignment, setAlignment] = useState(firebaseState.userId || "manish");

  const [unlockedUser, setUnlockedUser] = useState<string | null>(() => {
    try {
      return localStorage.getItem(UNLOCKED_USER_KEY);
    } catch {
      return null;
    }
  });

  const [validityState, setValidityState] = useState<{
    [index: number]: boolean;
  }>({});

  // Reset validityState when the user changes
  useEffect(() => {
    const initialValidityState = userConfig[alignment]?.authSlots.reduce(
      (acc, _, index) => ({ ...acc, [index]: false }),
      {},
    );
    setValidityState(initialValidityState || {});
  }, [alignment]);

  const handleLock = () => {
    try {
      localStorage.removeItem(UNLOCKED_USER_KEY);
    } catch {
      // ignore storage errors (e.g. private browsing)
    }
    setUnlockedUser(null);
    window.location.reload();
  };

  const handleChange = (event: any, newValue: number) => {
    setValue(newValue);
  };

  const handleToggle = (
    event: React.MouseEvent<HTMLElement>,
    newAlignment: string | null,
  ) => {
    if (newAlignment) {
      setAlignment(newAlignment);
      firebaseDispatch({ type: "changeId", payload: newAlignment });
    }
  };

  const handleOnChange = (isValid: boolean, index: number) => {
    setValidityState((prev) => ({
      ...prev,
      [index]: isValid,
    }));
  };

  const expectedSlotCount = userConfig[alignment]?.authSlots.length ?? 0;
  const slotsValid =
    expectedSlotCount > 0 &&
    Object.keys(validityState).length === expectedSlotCount &&
    Object.values(validityState).every((isValid) => isValid);
  const allValid = slotsValid || unlockedUser === alignment;

  // Persist unlock so refreshes don't drop the user back to the swipe screen
  useEffect(() => {
    if (slotsValid && unlockedUser !== alignment) {
      try {
        localStorage.setItem(UNLOCKED_USER_KEY, alignment);
      } catch {
        // ignore storage errors (e.g. private browsing)
      }
      setUnlockedUser(alignment);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [slotsValid, alignment]);

  return !state?.isLoggedIn ? (
    <div className="app-shell">
      <div className="app-atmosphere" aria-hidden="true" />
      {themeKey === "sketchbook" && <DoodleField />}
      {allValid ? (
        <>
          <UserHeader userId={alignment} onLock={handleLock} />
          <motion.div
            className="app-content"
            initial={{ opacity: 0, y: 12 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.4, ease: "easeOut" }}
          >
            <Tabs
              value={value}
              onChange={handleChange}
              variant="fullWidth"
              aria-label="tabs"
              sx={{ mb: 2 }}
            >
              <Tab label="Items" />
              <Tab label="Category" />
            </Tabs>
            <AnimatePresence mode="wait">
              {value === 0 && (
                <TabPanel key="items" value={value} index={0}>
                  <Items />
                </TabPanel>
              )}
              {value === 1 && (
                <TabPanel key="category" value={value} index={1}>
                  <Category />
                </TabPanel>
              )}
            </AnimatePresence>
          </motion.div>
        </>
      ) : (
        <div className="auth-container-inp">
          <motion.div
            className="auth-panel"
            initial={{ opacity: 0, y: 24, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            transition={{ duration: 0.5, ease: "easeOut" }}
          >
            <OccasionDoodle />
            <div className="auth-theme-switcher">
              <ThemeSwitcher />
            </div>
            <div className="auth-header">
              <p className="auth-eyebrow">Welcome back</p>
              <h1>Unlock your dashboard</h1>
            </div>

            <ToggleButtonGroup
              color="secondary"
              value={alignment}
              exclusive
              onChange={handleToggle}
              aria-label="User Selection"
              className="auth-user-selector"
              sx={{
                display: "flex",
                flexWrap: "wrap",
                justifyContent: "center",
                width: "100%",
                gap: 1,
              }}
            >
              {myUsers.map((user) => (
                <ToggleButton
                  key={user}
                  value={user}
                  aria-label={`Select user ${userConfig[user]?.label ?? user}`}
                >
                  {userConfig[user]?.label ?? user}
                </ToggleButton>
              ))}
            </ToggleButtonGroup>

            <div className="my-slider-container">
              {userConfig[alignment]?.authSlots.map((config, index) => (
                <Auth
                  key={index}
                  config={config}
                  onChangeHandlerValue={(isValid) =>
                    handleOnChange(isValid, index)
                  }
                />
              ))}
            </div>
          </motion.div>
        </div>
      )}
    </div>
  ) : (
    <div className="app-shell">
      <div className="app-atmosphere" aria-hidden="true" />
      {themeKey === "sketchbook" && <DoodleField />}
      <Header />
    </div>
  );
}

function TabPanel(props: any) {
  const { children, value, index } = props;

  return (
    <motion.div
      role="tabpanel"
      id={`tabpanel-${index}`}
      aria-labelledby={`tab-${index}`}
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -10 }}
      transition={{ duration: 0.25, ease: "easeOut" }}
    >
      {value === index && <Box p={0}>{children}</Box>}
    </motion.div>
  );
}

export default App;
