import React, { useMemo } from "react";
import {
  Chart as ChartJS,
  LinearScale,
  PointElement,
  Tooltip,
  Legend,
  BubbleController,
} from "chart.js";
import { Bubble } from "react-chartjs-2";
import { Box, Typography } from "@mui/material";
import { IItems, ICategoryProps } from "../../context/DataStateModels";
import { getCategoryColor } from "../../Utils/Utils";
import { tokens, themeVersion } from "../../../theme";

ChartJS.register(LinearScale, PointElement, Tooltip, Legend, BubbleController);

interface SpendBubbleFieldProps {
  items: IItems[];
  categories: ICategoryProps[];
}

type BubblePoint = {
  x: number;
  y: number;
  r: number;
  item: IItems;
};

const radiusFromPrice = (price: number): number =>
  Math.min(26, Math.max(4, 4 + Math.sqrt(price) * 0.6));

const SpendBubbleField: React.FC<SpendBubbleFieldProps> = ({ items, categories }) => {
  const { datasets, hasData } = useMemo(() => {
    const valid = items.filter((it) => it?.date && !isNaN(new Date(it.date).getTime()));
    if (valid.length === 0) return { datasets: [], hasData: false };

    const sorted = [...valid].sort(
      (a, b) => new Date(a.date).getTime() - new Date(b.date).getTime(),
    );
    const earliest = new Date(sorted[0].date).getTime();

    const byCategory = new Map<string, BubblePoint[]>();
    sorted.forEach((it) => {
      const price = parseFloat(String(it.price || 0));
      const x = Math.floor((new Date(it.date).getTime() - earliest) / 86400000);
      const point: BubblePoint = { x, y: price, r: radiusFromPrice(price), item: it };
      const key = it.category || "uncategorized";
      if (!byCategory.has(key)) byCategory.set(key, []);
      byCategory.get(key)!.push(point);
    });

    const ds = Array.from(byCategory.entries()).map(([categoryId, points]) => {
      const color = getCategoryColor(categoryId);
      const name =
        categories.find((c) => c.id === categoryId)?.name || "Uncategorized";
      return {
        label: name,
        data: points,
        backgroundColor: `${color}99`,
        borderColor: color,
        borderWidth: 1,
        hoverBackgroundColor: color,
      };
    });

    return { datasets: ds, hasData: true };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [items, categories, themeVersion]);

  if (!hasData) {
    return (
      <>
        <Typography variant="subtitle1">Spend Constellation</Typography>
        <Box
          display="flex"
          alignItems="center"
          justifyContent="center"
          p={4}
          sx={{ color: "text.secondary" }}
        >
          <Typography variant="body2">No data yet</Typography>
        </Box>
      </>
    );
  }

  const options = {
    maintainAspectRatio: true,
    scales: {
      x: {
        type: "linear" as const,
        ticks: { display: false },
        title: { display: true, text: "Time →", color: tokens.textMuted },
      },
      y: {
        type: "linear" as const,
        ticks: {
          callback: (v: number | string) => `₹${Number(v).toLocaleString("en-IN")}`,
          font: { size: 10 },
        },
      },
    },
    plugins: {
      legend: { display: true },
      tooltip: {
        callbacks: {
          label: (ctx: any) => {
            const point = ctx.raw as BubblePoint;
            const item = point.item;
            const price = parseFloat(String(item.price || 0));
            const date = new Date(item.date).toLocaleDateString();
            return `${item.name || "Unnamed"} — ₹${price.toLocaleString("en-IN")} (${date})`;
          },
        },
      },
    },
  };

  return (
    <>
      <Typography variant="subtitle1">Spend Constellation</Typography>
      <Bubble data={{ datasets }} options={options} redraw />
    </>
  );
};

export default SpendBubbleField;
