export const THEME_LIST = Object.values(THEMES);
export const DEFAULT_THEME_KEY = "nightfall";

// --- Mutable runtime state -------------------------------------------------
// These stay as stable object/array references so every existing `import {
// tokens } from "../../theme"` call site keeps working unchanged — switching
// themes mutates the *contents* in place (never reassigns the binding), and
// since plain property/array reads happen fresh on every render, consumers
// pick up the new values automatically without themselves needing to know a
// theme system exists. `themeVersion` is the one thing components must add
// to a useMemo's dependency array when memoized output embeds a token color
// (a plain property read doesn't retrigger memoization on its own).
export const tokens: ThemeTokens = { ...THEMES[DEFAULT_THEME_KEY].tokens };
export const categoryPalette: string[] = [
  tokens.violet,
  tokens.cyan,
  tokens.amber,
  tokens.emerald,
  tokens.rose,
  tokens.sky,
  tokens.fuchsia,
  tokens.lime,
];
export let gradientBrand = THEMES[DEFAULT_THEME_KEY].gradientBrand;
export let gradientMoney = THEMES[DEFAULT_THEME_KEY].gradientMoney;
export let fontMono = THEMES[DEFAULT_THEME_KEY].fontMono;
export let fontDisplay = THEMES[DEFAULT_THEME_KEY].fontDisplay;
export let themeVersion = 0;

const CSS_VAR_MAP = (def: ThemeDefinition): Record<string, string> => ({
  "--bg-void": def.tokens.bgVoid,
  "--bg-deep": def.tokens.bgDeep,
  "--bg-panel": def.tokens.bgPanel,
  "--bg-panel-strong": def.tokens.bgPanelStrong,
  "--panel-border": def.tokens.panelBorder,
  "--text-primary": def.tokens.textPrimary,
  "--text-muted": def.tokens.textMuted,
  "--accent-1": def.tokens.violet,
  "--accent-2": def.tokens.cyan,
  "--money": def.tokens.amber,
  "--success": def.tokens.emerald,
  "--danger": def.tokens.rose,
  "--grid-line": def.tokens.gridLine,
  "--neutral-fill": def.tokens.neutralFill,
  "--font-display": def.fontDisplay,
  "--font-mono": def.fontMono,
  "--panel-radius": `${def.panelRadius}px`,
  "--control-radius": `${def.controlRadius}px`,
  "--panel-blur": def.panelBlur === "none" ? "none" : def.panelBlur,
  "--panel-shadow": def.panelShadow,
  "--panel-border-width": def.panelBorderWidth,
  "--gradient-brand": def.gradientBrand,
  "--gradient-money": def.gradientMoney,
  "--on-accent": def.onAccent,
  "--table-header": `${def.tokens.violet}29`,
  "--shadow-theme-hover": def.panelBlur === "none" ? "none" : `0 14px 34px ${def.tokens.violet}40`,
  "--shadow-theme-focus": `0 0 0 3px ${def.tokens.cyan}55`,
  "--selected-item": `${def.tokens.violet}29`,
});

export const applyThemeTokens = (key: string): ThemeDefinition => {
  const def = THEMES[key] || THEMES[DEFAULT_THEME_KEY];

  Object.assign(tokens, def.tokens);
  categoryPalette.splice(
    0,
    categoryPalette.length,
    def.tokens.violet,
    def.tokens.cyan,
    def.tokens.amber,
    def.tokens.emerald,
    def.tokens.rose,
    def.tokens.sky,
    def.tokens.fuchsia,
    def.tokens.lime,
  );
  gradientBrand = def.gradientBrand;
  gradientMoney = def.gradientMoney;
  fontMono = def.fontMono;
  fontDisplay = def.fontDisplay;
  themeVersion += 1;

  const root = document.documentElement;
  root.setAttribute("data-app-theme", def.key);
  const vars = CSS_VAR_MAP(def);
  Object.entries(vars).forEach(([k, v]) => root.style.setProperty(k, v));

  return def;
};

export const buildMuiTheme = (def: ThemeDefinition): Theme => {
  const t = def.tokens;
  const glass = def.panelBlur !== "none";

  return createTheme({
    palette: {
      mode: "dark",
      background: { default: t.bgVoid, paper: t.bgDeep },
      primary: { main: t.violet, contrastText: def.onAccent },
      secondary: { main: t.cyan, contrastText: def.onAccent },
      text: { primary: t.textPrimary, secondary: t.textMuted },
      divider: t.panelBorder,
    },
    shape: { borderRadius: def.panelRadius },
    typography: {
      fontFamily: '"Inter", sans-serif',
      h1: { fontFamily: def.fontDisplay },
      h2: { fontFamily: def.fontDisplay },
      h3: { fontFamily: def.fontDisplay },
      h4: { fontFamily: def.fontDisplay },
      h5: { fontFamily: def.fontDisplay, fontWeight: 600 },
      h6: { fontFamily: def.fontDisplay, fontWeight: 600 },
      subtitle1: { fontFamily: def.fontDisplay, fontWeight: 600 },
      subtitle2: { fontFamily: def.fontDisplay, fontWeight: 600 },
      button: { fontFamily: def.fontDisplay, fontWeight: 600, textTransform: "none" },
    },
    components: {
      MuiCssBaseline: {
        styleOverrides: {
          body: { backgroundColor: t.bgVoid, colorScheme: glass ? "dark" : "normal" },
          "*::-webkit-scrollbar": { width: 10, height: 10 },
          "*::-webkit-scrollbar-track": { background: "transparent" },
          "*::-webkit-scrollbar-thumb": { background: t.panelBorder, borderRadius: 8 },
          "*::-webkit-scrollbar-thumb:hover": { background: t.violet },
        },
      },
      MuiAppBar: {
        styleOverrides: {
          root: {
            backgroundImage: "none",
            backgroundColor: def.appBarBg,
            backdropFilter: glass ? "blur(18px) saturate(160%)" : "none",
            WebkitBackdropFilter: glass ? "blur(18px) saturate(160%)" : "none",
            borderBottom: `${def.panelBorderWidth} solid ${t.panelBorder}`,
            boxShadow: glass ? "0 8px 32px rgba(0,0,0,0.4)" : "none",
            color: t.textPrimary,
          },
        },
      },
      MuiPaper: {
        styleOverrides: {
          root: {
            backgroundImage: "none",
            backgroundColor: t.bgPanel,
            backdropFilter: def.panelBlur === "none" ? "none" : def.panelBlur,
            WebkitBackdropFilter: def.panelBlur === "none" ? "none" : def.panelBlur,
            border: `${def.panelBorderWidth} solid ${t.panelBorder}`,
            boxShadow: def.panelShadow,
            color: t.textPrimary,
          },
        },
      },
      MuiButton: {
        styleOverrides: {
          root: {
            borderRadius: def.controlRadius,
            padding: "9px 20px",
            transition: "transform 0.18s ease, box-shadow 0.18s ease",
          },
          contained: {
            backgroundImage: def.gradientBrand,
            color: def.onAccent,
            boxShadow: glass ? `0 8px 24px ${t.violet}55` : "none",
            "&:hover": {
              backgroundImage: def.gradientBrand,
              transform: "translateY(-1px)",
              boxShadow: glass ? `0 12px 30px ${t.cyan}66` : "none",
              filter: glass ? "none" : "brightness(1.08)",
            },
            "&:active": { transform: "translateY(0)" },
            "&.Mui-disabled": {
              backgroundImage: "none",
              backgroundColor: t.panelBorder,
              color: t.textMuted,
            },
          },
          outlined: {
            borderColor: t.panelBorder,
            color: t.textPrimary,
            "&:hover": { borderColor: t.violet, backgroundColor: `${t.violet}18` },
          },
          text: { color: t.textPrimary },
        },
      },
      MuiToggleButtonGroup: {
        styleOverrides: {
          root: {
            backgroundColor: t.bgPanelStrong,
            borderRadius: def.controlRadius,
            padding: 4,
            gap: 4,
          },
        },
      },
      MuiToggleButton: {
        styleOverrides: {
          root: {
            border: "none",
            borderRadius: def.controlRadius,
            textTransform: "none",
            fontFamily: def.fontDisplay,
            fontWeight: 600,
            color: t.textMuted,
            "&.Mui-selected": {
              backgroundImage: def.gradientBrand,
              color: def.onAccent,
              "&:hover": { backgroundImage: def.gradientBrand },
            },
          },
        },
      },
      MuiTabs: {
        styleOverrides: {
          root: {
            minHeight: 44,
            backgroundColor: t.bgPanelStrong,
            borderRadius: def.controlRadius,
            padding: 4,
          },
          indicator: {
            height: "100%",
            borderRadius: def.controlRadius,
            backgroundImage: def.gradientBrand,
            zIndex: 0,
          },
        },
      },
      MuiTab: {
        styleOverrides: {
          root: {
            zIndex: 1,
            minHeight: 36,
            borderRadius: def.controlRadius,
            fontFamily: def.fontDisplay,
            fontWeight: 600,
            textTransform: "none",
            color: t.textMuted,
            transition: "color 0.2s ease",
            "&.Mui-selected": { color: def.onAccent },
          },
        },
      },
      MuiTextField: { defaultProps: { variant: "outlined" } },
      MuiOutlinedInput: {
        styleOverrides: {
          root: {
            borderRadius: Math.min(def.panelRadius, 14),
            backgroundColor: t.bgPanelStrong,
            color: t.textPrimary,
            transition: "border-color 0.2s ease, background-color 0.2s ease",
            "& fieldset": { borderColor: t.panelBorder },
            "&:hover fieldset": { borderColor: t.cyan },
            "&.Mui-focused": { backgroundColor: `${t.violet}12` },
            "&.Mui-focused fieldset": { borderColor: t.cyan, borderWidth: 1.5 },
          },
        },
      },
      MuiInputLabel: {
        styleOverrides: { root: { color: t.textMuted, "&.Mui-focused": { color: t.cyan } } },
      },
      MuiSelect: { styleOverrides: { root: { borderRadius: Math.min(def.panelRadius, 14) } } },
      MuiMenu: {
        styleOverrides: {
          paper: {
            backgroundColor: def.menuBg,
            backdropFilter: glass ? "blur(20px)" : "none",
            border: `${def.panelBorderWidth} solid ${t.panelBorder}`,
            color: t.textPrimary,
          },
        },
      },
      MuiMenuItem: { styleOverrides: { root: { color: t.textPrimary } } },
      MuiIconButton: {
        styleOverrides: {
          root: {
            color: t.textPrimary,
            transition: "transform 0.18s ease, background-color 0.18s ease",
            "&:hover": { transform: "translateY(-1px) scale(1.05)", backgroundColor: `${t.cyan}22` },
          },
        },
      },
      MuiTypography: { styleOverrides: { root: { color: t.textPrimary } } },
    },
  });
};
