import React, { useMemo } from "react";
import {
  Chart as ChartJS,
  RadialLinearScale,
  PointElement,
  LineElement,
  Filler,
  Tooltip,
  Legend,
} from "chart.js";
import { Radar } from "react-chartjs-2";
import { Box, Typography } from "@mui/material";
import { IItems, ICategoryProps } from "../../context/DataStateModels";
import { tokens, themeVersion } from "../../../theme";
import { getCategoryColor } from "../../Utils/Utils";

ChartJS.register(RadialLinearScale, PointElement, LineElement, Filler, Tooltip, Legend);

interface RadarSpendProfileProps {
  items: IItems[];
  categories: ICategoryProps[];
}

const MAX_AXES = 8;

const RadarSpendProfile: React.FC<RadarSpendProfileProps> = ({ items, categories }) => {
  const axes = useMemo(() => {
    const map = new Map<string, number>();
    items.forEach((it) => {
      const key = it.category || "uncategorized";
      const amount = parseFloat(String(it.price || 0));
      map.set(key, (map.get(key) || 0) + amount);
    });

    const withNames = Array.from(map.entries())
      .filter(([, total]) => total > 0)
      .map(([categoryId, total]) => ({
        categoryId,
        name: categories.find((c) => c.id === categoryId)?.name || "Uncategorized",
        total,
      }))
      .sort((a, b) => b.total - a.total)
      .slice(0, MAX_AXES);

    return withNames;
  }, [items, categories]);

  const chartData = useMemo(() => {
    if (axes.length === 0) return null;
    const maxTotal = axes[0].total;
    return {
      labels: axes.map((a) => a.name),
      datasets: [
        {
          label: "Spend %",
          data: axes.map((a) => (maxTotal > 0 ? (a.total / maxTotal) * 100 : 0)),
          backgroundColor: `${tokens.violet}4D`,
          borderColor: tokens.violet,
          fill: true,
          pointBackgroundColor: axes.map((a) => getCategoryColor(a.categoryId)),
          pointBorderColor: tokens.bgDeep,
          pointRadius: 4,
          pointHoverRadius: 5,
        },
      ],
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [axes, themeVersion]);

  const options = {
    maintainAspectRatio: true,
    plugins: {
      tooltip: {
        callbacks: {
          label: (ctx: any) => {
            const idx = ctx.dataIndex;
            const amount = axes[idx]?.total || 0;
            return `${axes[idx]?.name}: ₹${amount.toLocaleString("en-IN")} (${Math.round(
              ctx.parsed.r,
            )}%)`;
          },
        },
      },
      legend: { display: false },
    },
    scales: {
      r: {
        min: 0,
        max: 100,
        ticks: { display: false },
        grid: { color: tokens.gridLine },
        angleLines: { color: tokens.gridLine },
        pointLabels: { color: tokens.textMuted, font: { size: 11 } },
      },
    },
  };

  return (
    <>
      <Typography variant="subtitle1">Spend Profile</Typography>
      {chartData && axes.length > 0 ? (
        <Radar data={chartData} options={options} redraw />
      ) : (
        <Box
          display="flex"
          alignItems="center"
          justifyContent="center"
          p={4}
          sx={{ color: "text.secondary" }}
        >
          <Typography variant="body2">No data yet</Typography>
        </Box>
      )}
    </>
  );
};

export default RadarSpendProfile;
