import { SVGProps } from "react";

const Diya = ({ cx, cy, s, color, opacity }: { cx: number; cy: number; s: number; color: string; opacity: number }) => (
  <g stroke={color} strokeLinecap="round" opacity={opacity}>
    <path d={`M${cx - s} ${cy} C ${cx - s} ${cy + s * 0.7}, ${cx + s} ${cy + s * 0.7}, ${cx + s} ${cy} C ${cx + s * 0.5} ${cy + s * 0.15}, ${cx - s * 0.5} ${cy + s * 0.15}, ${cx - s} ${cy} Z`} strokeWidth={1.5} />
    <path d={`M${cx} ${cy - s * 0.3} C ${cx - s * 0.35} ${cy - s * 0.9}, ${cx + s * 0.35} ${cy - s * 1.3}, ${cx} ${cy - s * 1.7}`} strokeWidth={1.3} opacity={0.85} />
  </g>
);

const DiwaliDoodle = (props: SVGProps<SVGSVGElement>) => (
  <svg viewBox="0 0 160 160" fill="none" {...props}>
    <Diya cx={44} cy={70} s={14} color="var(--money)" opacity={0.85} />
    <Diya cx={92} cy={92} s={10} color="var(--accent-1)" opacity={0.7} />
    <g stroke="var(--accent-2)" strokeLinecap="round" opacity={0.6}>
      {[0, 45, 90, 135, 180, 225, 270, 315].map((angle) => {
        const rad = (angle * Math.PI) / 180;
        const x1 = 118 + Math.cos(rad) * 6;
        const y1 = 34 + Math.sin(rad) * 6;
        const x2 = 118 + Math.cos(rad) * 12;
        const y2 = 34 + Math.sin(rad) * 12;
        return <line key={angle} x1={x1} y1={y1} x2={x2} y2={y2} strokeWidth={1.2} />;
      })}
    </g>
    <circle cx={22} cy={38} r={1.8} fill="var(--money)" opacity={0.6} />
    <circle cx={132} cy={90} r={1.6} fill="var(--accent-1)" opacity={0.5} />
  </svg>
);

export default DiwaliDoodle;
