import { useMemo } from "react";
import { ALL_DOODLE_ICONS } from "./icons";

// A cheap seedable PRNG (mulberry32) so one Math.random() call seeds a whole
// field of icons deterministically for the life of this mount, instead of
// calling Math.random() dozens of times inline (harder to reason about).
function mulberry32(seed: number) {
  return () => {
    seed |= 0;
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const PALETTE = [
  "#FF6B6B",
  "#2EC4B6",
  "#FFD166",
  "#06D6A0",
  "#EF476F",
  "#4CC9F0",
  "#C77DFF",
  "#F72585",
  "#3A86FF",
  "#FFBE0B",
];

const COUNT = 36;
const COLUMNS = 6;

// Scattered across the *whole* scrollable page (not just one viewport), so
// wherever a card leaves a gap — top margin, bottom margin, the strip
// beside a centered panel, the seam between two stacked cards — there's a
// good chance a doodle is sitting right there. True background: absolute,
// negative z-index, zero pointer-events, re-rolled once per mount (i.e.
// once per visit) so the palette/layout is different every time you open
// the app, per request.
const DoodleField = () => {
  const items = useMemo(() => {
    const rand = mulberry32(Math.floor(Math.random() * 2 ** 31));
    const rows = Math.ceil(COUNT / COLUMNS);
    const rowSpan = 100 / rows;
    const colSpan = 100 / COLUMNS;

    return Array.from({ length: COUNT }, (_, i) => {
      const Icon = ALL_DOODLE_ICONS[Math.floor(rand() * ALL_DOODLE_ICONS.length)];
      const col = i % COLUMNS;
      const row = Math.floor(i / COLUMNS);
      const left = col * colSpan + colSpan / 2 + (rand() * colSpan * 0.6 - colSpan * 0.3);
      const top = row * rowSpan + rowSpan / 2 + (rand() * rowSpan * 0.6 - rowSpan * 0.3);
      const size = 60 + rand() * 52;
      const rotate = rand() * 32 - 16;
      const color = PALETTE[Math.floor(rand() * PALETTE.length)];
      const opacity = 0.4 + rand() * 0.35;

      return { key: i, Icon, left, top, size, rotate, color, opacity };
    });
  }, []);

  return (
    <div className="doodle-field" aria-hidden="true">
      {items.map(({ key, Icon, left, top, size, rotate, color, opacity }) => (
        <Icon
          key={key}
          className="doodle-field-icon"
          style={{
            left: `${left}%`,
            top: `${top}%`,
            width: size,
            height: size,
            color,
            opacity,
            ["--doodle-i" as string]: key,
            transform: `translate(-50%, -50%) rotate(${rotate}deg)`,
          }}
        />
      ))}
    </div>
  );
};

export default DoodleField;
