import { ComponentType, SVGProps } from "react";
import WinterDoodle from "./motifs/WinterDoodle";
import NewYearDoodle from "./motifs/NewYearDoodle";
import RepublicDayDoodle from "./motifs/RepublicDayDoodle";
import BlossomDoodle from "./motifs/BlossomDoodle";
import ValentineDoodle from "./motifs/ValentineDoodle";
import HoliDoodle from "./motifs/HoliDoodle";
import SunDoodle from "./motifs/SunDoodle";
import MonsoonDoodle from "./motifs/MonsoonDoodle";
import KiteDoodle from "./motifs/KiteDoodle";
import IndependenceDayDoodle from "./motifs/IndependenceDayDoodle";
import GaneshDoodle from "./motifs/GaneshDoodle";
import MarigoldDoodle from "./motifs/MarigoldDoodle";
import DiwaliDoodle from "./motifs/DiwaliDoodle";
import ChristmasDoodle from "./motifs/ChristmasDoodle";

export interface SeasonalDoodle {
  key: string;
  label: string;
  Component: ComponentType<SVGProps<SVGSVGElement>>;
}

const isDate = (date: Date, month: number, day: number) =>
  date.getMonth() === month && date.getDate() === day;

const MONTH_DOODLES: Record<number, SeasonalDoodle> = {
  0: { key: "winter", label: "Winter", Component: WinterDoodle },
  1: { key: "blossom", label: "Late-winter blossom", Component: BlossomDoodle },
  2: { key: "holi", label: "Holi season", Component: HoliDoodle },
  3: { key: "blossom-spring", label: "Spring blossom", Component: BlossomDoodle },
  4: { key: "sun", label: "Summer", Component: SunDoodle },
  5: { key: "monsoon-early", label: "Monsoon onset", Component: MonsoonDoodle },
  6: { key: "monsoon", label: "Monsoon", Component: MonsoonDoodle },
  7: { key: "kites", label: "Kite & Raksha Bandhan season", Component: KiteDoodle },
  8: { key: "ganesh", label: "Ganesh Chaturthi season", Component: GaneshDoodle },
  9: { key: "marigold", label: "Navratri season", Component: MarigoldDoodle },
  10: { key: "diwali", label: "Diwali season", Component: DiwaliDoodle },
  11: { key: "festive-winter", label: "Festive winter", Component: WinterDoodle },
};

export const getSeasonalDoodle = (date: Date): SeasonalDoodle => {
  if (isDate(date, 0, 1)) return { key: "new-year", label: "New Year's Day", Component: NewYearDoodle };
  if (isDate(date, 0, 26)) return { key: "republic-day", label: "Republic Day", Component: RepublicDayDoodle };
  if (isDate(date, 1, 14)) return { key: "valentine", label: "Valentine's Day", Component: ValentineDoodle };
  if (isDate(date, 7, 15)) return { key: "independence-day", label: "Independence Day", Component: IndependenceDayDoodle };
  if (isDate(date, 11, 25)) return { key: "christmas", label: "Christmas", Component: ChristmasDoodle };

  return MONTH_DOODLES[date.getMonth()] ?? MONTH_DOODLES[0];
};
