import React, { useState } from "react";
import "./auth.scss";

type authConfig = {
  defaultValue: number;
  valid: number;
};

interface IAuthProps {
  config: authConfig;
  onChangeHandlerValue: (e: boolean) => void;
}

const Auth = ({ config, onChangeHandlerValue }: IAuthProps) => {
  const [slideValue, setSlideValue] = useState<number>(config.defaultValue);

  React.useEffect(() => {
    // Notify parent of initial validity based on default value
    onChangeHandlerValue(
      config.defaultValue?.toString() === config.valid?.toString(),
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const updateValue = (nextValue: number) => {
    const boundedValue = Math.min(100, Math.max(0, nextValue));
    setSlideValue(boundedValue);
    onChangeHandlerValue(boundedValue?.toString() === config.valid.toString());
  };

  const handleSlider = (e: React.ChangeEvent<HTMLInputElement>) => {
    const nextValue = Number(e.target.value);
    updateValue(nextValue);
  };

  const handleIncrement = () => updateValue(slideValue + 1);
  const handleDecrement = () => updateValue(slideValue - 1);

  return (
    <div className="auth-container">
      <span className="slider-value">{slideValue}</span>
      <div className="slider-controls">
        <button
          type="button"
          className="slider-step-btn"
          onClick={handleDecrement}
          aria-label="Decrease slider value"
        >
          −
        </button>

        <div
          className="child-auth-silders vertical-slider"
          key={config.defaultValue}
        >
          <div className="slider-wrapper">
            <input
              className="my-slider-face vertical"
              name="slider"
              type="range"
              value={slideValue}
              defaultValue={config.defaultValue}
              onChange={handleSlider}
              min="0"
              max="100"
            />
          </div>
        </div>

        <button
          type="button"
          className="slider-step-btn"
          onClick={handleIncrement}
          aria-label="Increase slider value"
        >
          +
        </button>
      </div>
    </div>
  );
};

export default Auth;
