import { SVGProps } from "react";

const Splash = ({ cx, cy, r, color }: { cx: number; cy: number; r: number; color: string }) => (
  <g stroke={color} strokeLinecap="round">
    <circle cx={cx} cy={cy} r={r} strokeWidth={1.4} opacity={0.7} />
    {[0, 45, 90, 135, 180, 225, 270, 315].map((angle) => {
      const rad = (angle * Math.PI) / 180;
      const x1 = cx + Math.cos(rad) * (r + 2);
      const y1 = cy + Math.sin(rad) * (r + 2);
      const x2 = cx + Math.cos(rad) * (r + 7);
      const y2 = cy + Math.sin(rad) * (r + 7);
      return <line key={angle} x1={x1} y1={y1} x2={x2} y2={y2} strokeWidth={1.3} opacity={0.55} />;
    })}
  </g>
);

const HoliDoodle = (props: SVGProps<SVGSVGElement>) => (
  <svg viewBox="0 0 160 160" fill="none" {...props}>
    <Splash cx={46} cy={44} r={12} color="var(--accent-1)" />
    <Splash cx={92} cy={30} r={7} color="var(--money)" />
    <Splash cx={104} cy={76} r={9} color="var(--accent-2)" />
    <Splash cx={62} cy={94} r={6} color="var(--success)" />
    <circle cx={22} cy={80} r={2} fill="var(--accent-1)" opacity={0.6} />
    <circle cx={120} cy={52} r={1.6} fill="var(--success)" opacity={0.6} />
    <circle cx={80} cy={64} r={1.8} fill="var(--money)" opacity={0.6} />
  </svg>
);

export default HoliDoodle;
