import React, { useMemo } from "react";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Tooltip,
  Legend,
} from "chart.js";
import { Bar } from "react-chartjs-2";
import { Box, Typography } from "@mui/material";
import { IItems, ICategoryProps } from "../../context/DataStateModels";
import { getCategoryColor } from "../../Utils/Utils";
import { tokens, themeVersion } from "../../../theme";

ChartJS.register(CategoryScale, LinearScale, BarElement, Tooltip, Legend);

const TOP_N = 5;

const formatCurrency = (value: number) => `₹${Math.round(value).toLocaleString("en-IN")}`;

type StackedCategoryTrendProps = {
  items: IItems[];
  categories: ICategoryProps[];
};

const StackedCategoryTrend: React.FC<StackedCategoryTrendProps> = ({ items, categories }) => {
  const { monthLabels, datasets, hasData } = useMemo(() => {
    if (!items.length) {
      return { monthLabels: [] as string[], datasets: [] as any[], hasData: false };
    }

    const categoryName = (id: string) =>
      categories.find((c) => c.id === id)?.name || "Uncategorized";

    const monthBuckets = new Map<string, { sortKey: number; label: string }>();
    const monthCategoryTotals = new Map<string, Map<string, number>>();
    const categoryTotals = new Map<string, number>();

    items.forEach((it) => {
      const d = new Date(it.date);
      if (isNaN(d.getTime())) return;
      const monthKey = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
      const label = d.toLocaleDateString("en-IN", { month: "short", year: "2-digit" });
      if (!monthBuckets.has(monthKey)) {
        monthBuckets.set(monthKey, {
          sortKey: new Date(d.getFullYear(), d.getMonth(), 1).getTime(),
          label,
        });
      }

      const price = parseFloat(String(it.price || 0)) || 0;
      const categoryId = it.category || "uncategorized";

      const monthMap = monthCategoryTotals.get(monthKey) || new Map<string, number>();
      monthMap.set(categoryId, (monthMap.get(categoryId) || 0) + price);
      monthCategoryTotals.set(monthKey, monthMap);

      categoryTotals.set(categoryId, (categoryTotals.get(categoryId) || 0) + price);
    });

    if (!monthBuckets.size) {
      return { monthLabels: [] as string[], datasets: [] as any[], hasData: false };
    }

    const orderedMonths = Array.from(monthBuckets.entries()).sort(
      (a, b) => a[1].sortKey - b[1].sortKey,
    );
    const monthKeys = orderedMonths.map(([key]) => key);
    const monthLabels = orderedMonths.map(([, v]) => v.label);

    const topCategoryIds = Array.from(categoryTotals.entries())
      .sort((a, b) => b[1] - a[1])
      .slice(0, TOP_N)
      .map(([id]) => id);
    const topCategorySet = new Set(topCategoryIds);

    const series = topCategoryIds.map((id) => ({
      id,
      name: categoryName(id),
      color: getCategoryColor(id),
    }));
    const hasOther = Array.from(categoryTotals.keys()).some((id) => !topCategorySet.has(id));

    const datasets = series.map(({ id, name, color }) => ({
      label: name,
      data: monthKeys.map((mk) => monthCategoryTotals.get(mk)?.get(id) || 0),
      backgroundColor: color,
      borderRadius: 4,
      stack: "spend",
    }));

    if (hasOther) {
      datasets.push({
        label: "Other",
        data: monthKeys.map((mk) => {
          const monthMap = monthCategoryTotals.get(mk);
          if (!monthMap) return 0;
          let sum = 0;
          monthMap.forEach((amount, id) => {
            if (!topCategorySet.has(id)) sum += amount;
          });
          return sum;
        }),
        backgroundColor: tokens.neutralFill,
        borderRadius: 4,
        stack: "spend",
      });
    }

    return { monthLabels, datasets, hasData: true };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [items, categories, themeVersion]);

  const data = { labels: monthLabels, datasets };

  const options = {
    maintainAspectRatio: true,
    scales: {
      x: {
        stacked: true,
        ticks: { maxRotation: 45, minRotation: 0, autoSkip: true, font: { size: 10 } },
      },
      y: {
        stacked: true,
        ticks: { font: { size: 10 } },
      },
    },
    plugins: {
      legend: { position: "bottom" as const },
      tooltip: {
        callbacks: {
          label: (ctx: any) => `${ctx.dataset.label}: ${formatCurrency(ctx.raw as number)}`,
        },
      },
    },
  };

  return (
    <>
      <Typography variant="subtitle1">Spend Trend by Category</Typography>
      {hasData ? (
        <Bar data={data} options={options} />
      ) : (
        <Box
          sx={{
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            minHeight: 200,
          }}
        >
          <Typography variant="body2" color="text.secondary">
            No data yet
          </Typography>
        </Box>
      )}
    </>
  );
};

export default StackedCategoryTrend;
