import { SVGProps } from "react";

const Flower = ({ cx, cy, r, color }: { cx: number; cy: number; r: number; color: string }) => (
  <g transform={`translate(${cx} ${cy})`} stroke={color} strokeLinecap="round">
    {Array.from({ length: 5 }).map((_, i) => {
      const angle = (i * 360) / 5;
      return (
        <ellipse
          key={i}
          cx={0}
          cy={-r}
          rx={r * 0.55}
          ry={r * 0.85}
          transform={`rotate(${angle})`}
          strokeWidth={1.2}
        />
      );
    })}
    <circle r={r * 0.35} fill={color} stroke="none" opacity={0.8} />
  </g>
);

const BlossomDoodle = (props: SVGProps<SVGSVGElement>) => (
  <svg viewBox="0 0 160 160" fill="none" {...props}>
    <path
      d="M10 130 C 40 110, 30 80, 60 60 S 90 30, 118 18"
      stroke="var(--accent-1)"
      strokeWidth={1.5}
      strokeLinecap="round"
      opacity={0.55}
    />
    <path d="M52 76 C 44 70, 40 78, 34 74" stroke="var(--success)" strokeWidth={1.3} opacity={0.6} />
    <path d="M78 46 C 86 40, 90 48, 96 44" stroke="var(--success)" strokeWidth={1.3} opacity={0.6} />
    <g opacity={0.85}>
      <Flower cx={58} cy={58} r={9} color="var(--accent-2)" />
    </g>
    <g opacity={0.75}>
      <Flower cx={92} cy={30} r={7} color="var(--money)" />
    </g>
    <g opacity={0.6}>
      <Flower cx={28} cy={104} r={6} color="var(--accent-1)" />
    </g>
  </svg>
);

export default BlossomDoodle;
