import { SVGProps } from "react";

const Burst = ({ cx, cy, r, color }: { cx: number; cy: number; r: number; color: string }) => (
  <g transform={`translate(${cx} ${cy})`} stroke={color} strokeLinecap="round">
    {Array.from({ length: 8 }).map((_, i) => {
      const angle = (i * 360) / 8;
      return (
        <line
          key={i}
          x1={0}
          y1={-r * 0.35}
          x2={0}
          y2={-r}
          transform={`rotate(${angle})`}
        />
      );
    })}
    <circle r={2} fill={color} stroke="none" />
  </g>
);

const NewYearDoodle = (props: SVGProps<SVGSVGElement>) => (
  <svg viewBox="0 0 160 160" fill="none" {...props}>
    <g strokeWidth={1.6} opacity={0.85}>
      <Burst cx={46} cy={42} r={22} color="var(--accent-2)" />
    </g>
    <g strokeWidth={1.4} opacity={0.7}>
      <Burst cx={104} cy={78} r={14} color="var(--money)" />
    </g>
    <path
      d="M20 108 C 34 96, 46 118, 60 104 S 84 116, 96 100"
      stroke="var(--accent-1)"
      strokeWidth={1.4}
      strokeLinecap="round"
      opacity={0.6}
    />
    <circle cx={128} cy={38} r={2} fill="var(--accent-1)" opacity={0.7} />
    <circle cx={78} cy={22} r={1.6} fill="var(--money)" opacity={0.6} />
  </svg>
);

export default NewYearDoodle;
