import {
  Typography,
  Box,
  Grid,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  TextField,
  TextareaAutosize,
} from "@mui/material";
import {
  addDoc,
  collection,
  deleteField,
  getDocs,
  updateDoc,
} from "firebase/firestore";
import { useEffect, useMemo, useState } from "react";
import { IItems } from "../context/DataStateModels";
// import { db } from "../../Firebase/config";
import { getDataScopeUserId, getFirebaseServices } from "../../Firebase/config";
import { useDataStateContext } from "../context/DataStateContext";
import {
  filterOwnDocs,
  getCategoryColor,
  IItemNCategoryFormProps,
  itemDoc,
  itemList,
  scopedQuery,
  TModes,
} from "../Utils/Utils";
import { uploadReceiptToDrive, deleteReceiptFromDrive } from "../Utils/googleDrive";
import { Skeleton, XFileReader } from "@manish774/smarty-ui";
import UploadIcon from "@mui/icons-material/Upload";
import CloseIcon from "@mui/icons-material/Close";
import RefreshIcon from "@mui/icons-material/Refresh";
import AddCircleRoundedIcon from "@mui/icons-material/AddCircleRounded";
import SaveRoundedIcon from "@mui/icons-material/SaveRounded";
import { useFireBase } from "../../context/FirebaseConfigContext";

const ItemsForm = ({ mode, id, handleMode }: IItemNCategoryFormProps) => {
  const { dispatch, state } = useDataStateContext();
  const [refreshToken, setRefreshToken] = useState<number>(0);
  const [isFormValid, setIsFormValid] = useState(false);
  const { state: firebaseState } = useFireBase();
  // const getFirebaseServices()
  const defaultDateTime = () => {
    const now = new Date();
    const year = now.getFullYear();
    const month = (now.getMonth() + 1).toString().padStart(2, "0");
    const day = now.getDate().toString().padStart(2, "0");
    const hours = now.getHours().toString().padStart(2, "0");
    const minutes = now.getMinutes().toString().padStart(2, "0");
    return `${year}-${month}-${day}T${hours}:${minutes}`;
  };
  const { db } = getFirebaseServices(firebaseState.userId);
  const scopeUserId = getDataScopeUserId(firebaseState.userId);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [removeExistingImage, setRemoveExistingImage] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const categoryList = useMemo(
    () => collection(db, "category"),
    [firebaseState]
  );

  const initData = {
    name: "",
    description: "",
    price: "",
    category: "",
    date: defaultDateTime(),
    revisit: "No",
    pmode: "PhonePe",
  };

  const [item, setItem] = useState<IItems>(initData);

  // Local preview for a freshly-picked file, before it's actually uploaded.
  useEffect(() => {
    if (!selectedFile) {
      setPreviewUrl(null);
      return;
    }
    const url = URL.createObjectURL(selectedFile);
    setPreviewUrl(url);
    return () => URL.revokeObjectURL(url);
  }, [selectedFile]);

  const displayImageUrl =
    previewUrl || (!removeExistingImage ? item.imageUrl : undefined);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setSelectedFile(file);
      setRemoveExistingImage(false);
    }
    e.target.value = "";
  };

  const clearImage = () => {
    setSelectedFile(null);
    setRemoveExistingImage(true);
  };

  const addItem = async () => {
    setIsFormValid(false);
    try {
      let imageFields: Record<string, any> = {};
      if (selectedFile) {
        setIsUploading(true);
        const { fileId, viewUrl } = await uploadReceiptToDrive(selectedFile);
        imageFields = { imageUrl: viewUrl, driveFileId: fileId };
        setIsUploading(false);
      }

      const payload = { ...item, ...imageFields };
      const adding = await addDoc(
        itemList(db),
        scopeUserId ? { ...payload, userId: scopeUserId } : payload
      );

      setItem(initData);
      setSelectedFile(null);
      setRemoveExistingImage(false);
      setRefreshToken((prev) => prev + 1);
    } catch (e) {
      console.log(e);
      setIsUploading(false);
    }
  };

  const handleItems = (e: any) => {
    const inputType = e?.target.name;
    setItem((prev) => ({
      ...prev,
      [inputType]: e.target.value,
    }));
  };

  useEffect(() => {
    dispatch({ type: "loading", payload: { type: "category", status: true } });

    const getCategory = async () => {
      try {
        const data = await getDocs(scopedQuery(categoryList, scopeUserId));
        const categoryData: any = data?.docs?.map((doc) => ({
          ...doc?.data(),
          id: doc?.id,
        }));
        dispatch({
          type: "addCategory",
          payload: filterOwnDocs(categoryData || [], firebaseState.userId),
        });
        setItem(initData);
        dispatch({
          type: "loading",
          payload: { type: "category", status: false },
        });
      } catch (e) {
        console.log(e);
        dispatch({ type: "addCategory", payload: [] });
      }
    };
    getCategory();
  }, [dispatch, categoryList, scopeUserId]);

  useEffect(() => {
    dispatch({ type: "loading", payload: { type: "items", status: true } });
    const getItems = async () => {
      try {
        // No server-side orderBy here on purpose: combining it with the
        // scoped `where(userId==)` filter would require a Firestore composite
        // index (a one-time backend console step) — sorting client-side avoids
        // that entirely, at negligible cost for this app's data volumes.
        const data = await getDocs(scopedQuery(itemList(db), scopeUserId));
        const itemData: any[] = filterOwnDocs(
          (data?.docs || []).map((doc) => ({
            ...doc?.data(),
            id: doc?.id,
            isEdit: false,
          })),
          firebaseState.userId
        );
        itemData.sort(
          (a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()
        );
        dispatch({ type: "addItems", payload: itemData });
        dispatch({
          type: "loading",
          payload: { type: "items", status: false },
        });
      } catch (e) {
        console.log(e);
        dispatch({ type: "addItems", payload: [] });
      }
    };
    getItems();
  }, [dispatch, refreshToken, scopeUserId]); // Include refreshToken in dependency array

  // Check if all required fields are filled in
  useEffect(() => {
    setIsFormValid(
      item.name !== "" &&
        item.category !== "" &&
        item.price !== "" &&
        item.date !== ""
    );
  }, [item]);

  useEffect(() => {
    if (mode === "EDIT" && id !== "") {
      const {
        category,
        price,
        description,
        name,
        date,
        revisit,
        pmode,
        imageUrl,
        driveFileId,
      } = state?.items?.find((item) => item?.id === id) as IItems;
      setItem({
        category,
        price,
        description,
        name,
        date,
        revisit,
        pmode,
        imageUrl,
        driveFileId,
      });
      setSelectedFile(null);
      setRemoveExistingImage(false);
    }
  }, [mode, id, state]);

  const updateItem = async () => {
    if (id && mode === "EDIT") {
      try {
        const oldDriveFileId = item.driveFileId;
        let imageFields: Record<string, any> = {};
        if (selectedFile) {
          setIsUploading(true);
          const { fileId, viewUrl } = await uploadReceiptToDrive(selectedFile);
          imageFields = { imageUrl: viewUrl, driveFileId: fileId };
          setIsUploading(false);
        } else if (removeExistingImage) {
          imageFields = { imageUrl: deleteField(), driveFileId: deleteField() };
        }

        const updatedItem = { ...item, ...imageFields };
        updateDoc(itemDoc(id, db), updatedItem as any);

        if ((selectedFile || removeExistingImage) && oldDriveFileId) {
          deleteReceiptFromDrive(oldDriveFileId);
        }

        const localImageFields =
          selectedFile || removeExistingImage
            ? selectedFile
              ? imageFields
              : { imageUrl: undefined, driveFileId: undefined }
            : {};
        const updatedItems = state?.items?.map((d) =>
          d?.id === id ? { ...item, ...localImageFields } : { ...d }
        );
        dispatch({
          type: "addItems",
          payload: updatedItems,
        });

        setItem(initData);
        setSelectedFile(null);
        setRemoveExistingImage(false);
        handleMode && handleMode("ADD", "");
        setRefreshToken((prev) => prev + 1);
      } catch (e) {
        console.log(e);
        setIsUploading(false);
      }
    }
  };

  const handleExelFileUpload = (data) => {
    console.log(data);
  };
  const isCategoryLoading = state?.loading.category;

  const sortedCategoryOptions = useMemo(() => {
    const allCategories = state?.category || [];
    const topLevel = allCategories.filter((cat) => !cat?.parentId);
    const childrenOf = (parentId?: string) =>
      allCategories.filter((cat) => cat?.parentId === parentId);
    const ordered: typeof allCategories = [];
    topLevel.forEach((parent) => {
      ordered.push(parent);
      childrenOf(parent?.id).forEach((child) => ordered.push(child));
    });
    const orderedIds = new Set(ordered.map((cat) => cat?.id));
    allCategories.forEach((cat) => {
      if (!orderedIds.has(cat?.id)) {
        ordered.push(cat);
      }
    });
    return ordered;
  }, [state?.category]);
  return (
    <div>
      <div className="container-item-head">
        <span className="left-item">
          {mode === "ADD" ? "Add Item" : "Edit Item"}
        </span>
        <button
          className="right-item"
          type="button"
          aria-label="Reset form"
          onClick={(e) => {
            e.preventDefault();
            handleMode("ADD", "");
            setItem(initData);
            setSelectedFile(null);
            setRemoveExistingImage(false);
          }}
        >
          <RefreshIcon fontSize="small" />
        </button>
      </div>
      <Box component="form" noValidate sx={{ mt: 3 }}>
        <Grid container spacing={2}>
          {/* Category */}
          <Grid item xs={12}>
            {!isCategoryLoading ? (
              <FormControl fullWidth>
                <InputLabel id="category-select-label">
                  {isCategoryLoading ? "Loading..." : "Category"}
                </InputLabel>
                <Select
                  labelId="category-select-label"
                  id="category-select"
                  value={item?.category}
                  label="Category"
                  name="category"
                  onChange={handleItems}
                >
                  {sortedCategoryOptions?.map((cat) => (
                    <MenuItem key={cat.id} value={cat.id}>
                      <span
                        className="category-color-dot"
                        style={{ backgroundColor: getCategoryColor(cat.id) }}
                      />
                      {cat.parentId ? `↳ ${cat.name}` : cat.name}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            ) : (
              <Skeleton type={"line"} style={{ height: "53px" }} />
            )}
          </Grid>

          {/* Item Name */}
          <Grid item xs={12}>
            {!isCategoryLoading ? (
              <TextField
                autoComplete="given-name"
                name="name"
                required
                fullWidth
                id="name"
                label="Item Name"
                value={item?.name}
                onChange={handleItems}
              />
            ) : (
              <Skeleton type={"line"} style={{ height: "53px" }} />
            )}
          </Grid>

          {/* Item Price */}
          <Grid container item xs={12} spacing={2}>
            <Grid item xs={12} sm={6}>
              {!isCategoryLoading ? (
                <TextField
                  autoComplete="given-name"
                  name="price"
                  required
                  fullWidth
                  id="price"
                  type="number"
                  label="Item Price"
                  value={item?.price}
                  onChange={handleItems}
                />
              ) : (
                <Skeleton type={"line"} style={{ height: "53px" }} />
              )}
            </Grid>

            {/* Date */}
            <Grid item xs={12} sm={6}>
              {!isCategoryLoading ? (
                <TextField
                  autoComplete="given-name"
                  name="date"
                  required
                  fullWidth
                  id="date"
                  type="datetime-local"
                  label="Date"
                  value={item?.date}
                  onChange={handleItems}
                />
              ) : (
                <Skeleton type={"line"} style={{ height: "53px" }} />
              )}
            </Grid>
          </Grid>

          {/* Description */}
          <Grid item xs={12}>
            {!isCategoryLoading ? (
              <TextareaAutosize
                minRows={3}
                name="description"
                onChange={handleItems}
                aria-label="Item Description"
                placeholder="Item Description"
                className="item-description-input"
                style={{ width: "98%" }}
                value={item?.description}
              />
            ) : (
              <Skeleton type={"line"} style={{ height: "53px" }} />
            )}
          </Grid>

          {/* Receipt photo */}
          <Grid item xs={12}>
            {!isCategoryLoading && (
              <div className="receipt-upload">
                <label className="receipt-upload-btn">
                  <UploadIcon fontSize="small" />
                  {displayImageUrl ? "Change photo" : "Attach receipt photo"}
                  <input
                    type="file"
                    accept="image/*"
                    onChange={handleFileChange}
                    style={{ display: "none" }}
                  />
                </label>
                {isUploading && (
                  <span className="receipt-upload-status">Uploading…</span>
                )}
                {displayImageUrl && (
                  <div className="receipt-preview">
                    <img src={displayImageUrl} alt="Receipt preview" />
                    <button
                      type="button"
                      className="receipt-preview-remove"
                      aria-label="Remove photo"
                      onClick={clearImage}
                    >
                      <CloseIcon fontSize="small" />
                    </button>
                  </div>
                )}
              </div>
            )}
          </Grid>

          {/* Revisit and Payment Mode */}
          <Grid container item xs={12} spacing={2}>
            <Grid item xs={6} sm={6}>
              <FormControl fullWidth>
                {!isCategoryLoading ? (
                  <>
                    <InputLabel id="revisit-select-label">
                      {"Revisit required?"}
                    </InputLabel>
                    <Select
                      labelId="revisit-select-label"
                      id="revisit-select"
                      value={item.revisit || initData?.revisit}
                      label="Revisit"
                      name="revisit"
                      onChange={handleItems}
                    >
                      {["No", "Yes"]?.map((cat) => (
                        <MenuItem key={cat} value={cat}>
                          {cat}
                        </MenuItem>
                      ))}
                    </Select>
                  </>
                ) : (
                  <Skeleton type={"line"} style={{ height: "53px" }} />
                )}
              </FormControl>
            </Grid>
            <Grid item xs={6} sm={6}>
              <FormControl fullWidth>
                {!isCategoryLoading ? (
                  <>
                    <InputLabel id="pmode-select-label">
                      {"Payment mode"}
                    </InputLabel>
                    <Select
                      labelId="pmode-select-label"
                      id="pmode-select"
                      value={item.pmode || initData?.pmode}
                      label="pmode"
                      name="pmode"
                      onChange={handleItems}
                    >
                      {[
                        "Cash",
                        "PhonePe",
                        "Gpay",
                        "Credit card",
                        "Debit card",
                        "Paytm",
                      ]?.map((cat) => (
                        <MenuItem key={cat} value={cat}>
                          {cat}
                        </MenuItem>
                      ))}
                    </Select>
                  </>
                ) : (
                  <Skeleton type={"line"} style={{ height: "53px" }} />
                )}
              </FormControl>
            </Grid>
          </Grid>

          {/* Add/Update Button */}
          <Grid item xs={12}>
            <button
              className={"add-item-btn"}
              onClick={(e) => {
                e.preventDefault();
                mode === "ADD" ? addItem() : updateItem();
              }}
              disabled={!isFormValid || isUploading} // Disable button if form is not valid or a photo is uploading
            >
              {mode === "ADD" ? (
                <AddCircleRoundedIcon fontSize="small" />
              ) : (
                <SaveRoundedIcon fontSize="small" />
              )}
              {isUploading ? "Uploading…" : mode === "ADD" ? "Add" : "Update"}
            </button>
          </Grid>
        </Grid>
      </Box>
    </div>
  );
};

export default ItemsForm;
