import { SVGProps } from "react";

const SunDoodle = (props: SVGProps<SVGSVGElement>) => (
  <svg viewBox="0 0 160 160" fill="none" {...props}>
    <g stroke="var(--money)" strokeLinecap="round">
      <circle cx={64} cy={56} r={20} strokeWidth={1.6} opacity={0.8} />
      {Array.from({ length: 10 }).map((_, i) => {
        const angle = (i * 360) / 10;
        const rad = (angle * Math.PI) / 180;
        const x1 = 64 + Math.cos(rad) * 26;
        const y1 = 56 + Math.sin(rad) * 26;
        const x2 = 64 + Math.cos(rad) * 36;
        const y2 = 56 + Math.sin(rad) * 36;
        return <line key={angle} x1={x1} y1={y1} x2={x2} y2={y2} strokeWidth={1.4} opacity={0.6} />;
      })}
    </g>
    <path
      d="M14 118 C 40 108, 60 122, 90 108 S 130 118, 146 106"
      stroke="var(--accent-2)"
      strokeWidth={1.4}
      strokeLinecap="round"
      opacity={0.5}
    />
  </svg>
);

export default SunDoodle;
