import React, {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useState,
} from "react";
import { ThemeProvider as MuiThemeProvider, CssBaseline } from "@mui/material";
import {
  applyThemeTokens,
  buildMuiTheme,
  DEFAULT_THEME_KEY,
  THEME_LIST,
  THEMES,
  ThemeDefinition,
} from "../theme";
import DataStateProvider from "../components/context/DataStateProvider";
import App from "../App";

const STORAGE_KEY = "dream-theme";

interface ThemeSwitcherValue {
  themeKey: string;
  theme: ThemeDefinition;
  themeList: ThemeDefinition[];
  setThemeKey: (key: string) => void;
}

const ThemeSwitcherContext = createContext<ThemeSwitcherValue | undefined>(undefined);

const readStoredThemeKey = (): string => {
  try {
    const stored = window.localStorage.getItem(STORAGE_KEY);
    return stored && THEMES[stored] ? stored : DEFAULT_THEME_KEY;
  } catch {
    return DEFAULT_THEME_KEY;
  }
};

export const ThemeSwitcherProvider = ({ children }: { children: React.ReactNode }) => {
  const [themeKey, setThemeKeyState] = useState<string>(readStoredThemeKey);

  // Mutate the shared runtime `tokens`/CSS vars synchronously during render
  // — NOT in a useEffect. An effect fires after this render commits, so
  // everything rendering in the same pass (App, ItemsList, the chart
  // components — anything reading the `tokens` singleton directly rather
  // than through this context) would still see the *previous* theme's
  // values and only pick up the change on some later, unrelated re-render.
  // applyThemeTokens is idempotent, so calling it during render (including
  // StrictMode's double-invoke) is safe.
  const theme = applyThemeTokens(themeKey);

  const setThemeKey = useCallback((key: string) => {
    if (!THEMES[key]) return;
    try {
      window.localStorage.setItem(STORAGE_KEY, key);
    } catch {
      // localStorage unavailable (private browsing etc) — theme still applies for this session
    }
    setThemeKeyState(key);
  }, []);

  const value = useMemo<ThemeSwitcherValue>(
    () => ({
      themeKey,
      theme,
      themeList: THEME_LIST,
      setThemeKey,
    }),
    [themeKey, theme, setThemeKey],
  );

  return (
    <ThemeSwitcherContext.Provider value={value}>{children}</ThemeSwitcherContext.Provider>
  );
};

export const useThemeSwitcher = (): ThemeSwitcherValue => {
  const ctx = useContext(ThemeSwitcherContext);
  if (!ctx) {
    throw new Error("useThemeSwitcher must be used within a ThemeSwitcherProvider");
  }
  return ctx;
};

// Bridges the theme context to MUI's ThemeProvider — this component is the
// one that actually consumes the context, so it (and everything it renders
// fresh below, i.e. the whole app) re-renders on every theme switch.
export const AppThemeBridge = () => {
  const { theme } = useThemeSwitcher();
  const muiTheme = useMemo(() => buildMuiTheme(theme), [theme]);

  return (
    <MuiThemeProvider theme={muiTheme}>
      <CssBaseline />
      <DataStateProvider>
        <React.StrictMode>
          <App />
        </React.StrictMode>
      </DataStateProvider>
    </MuiThemeProvider>
  );
};
