import React, { useMemo } from "react";
import { Box, Typography } from "@mui/material";
import { IItems, ICategoryProps } from "../../context/DataStateModels";
import { tokens } from "../../../theme";
import "./SpendHeatmapCalendar.scss";

interface SpendHeatmapCalendarProps {
  items: IItems[];
  categories: ICategoryProps[];
}

interface DayCell {
  date: Date;
  key: string;
  amount: number;
}

const WEEKDAY_LABELS = ["S", "M", "T", "W", "T", "F", "S"];
const MONTH_LABELS = [
  "Jan", "Feb", "Mar", "Apr", "May", "Jun",
  "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
];
const MAX_WEEKS = 16;

const dayKey = (d: Date) => `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;

const startOfDay = (d: Date) => {
  const copy = new Date(d);
  copy.setHours(0, 0, 0, 0);
  return copy;
};

const intensityLevel = (amount: number, max: number): number => {
  if (amount <= 0 || max <= 0) return 0;
  const ratio = amount / max;
  if (ratio <= 0.2) return 1;
  if (ratio <= 0.45) return 2;
  if (ratio <= 0.75) return 3;
  return 4;
};

const SpendHeatmapCalendar: React.FC<SpendHeatmapCalendarProps> = ({ items }) => {
  // Recomputed every render (cheap, 5 entries) so it always reflects the
  // active theme's accent color rather than freezing at first paint.
  const LEVEL_COLORS = [
    `${tokens.violet}14`,
    `${tokens.violet}52`,
    `${tokens.violet}94`,
    `${tokens.violet}CC`,
    tokens.violet,
  ];

  const { weeks, monthMarkers, maxAmount } = useMemo(() => {
    if (items.length === 0) {
      return { weeks: [] as DayCell[][], monthMarkers: [] as { week: number; label: string }[], maxAmount: 0 };
    }

    const spendByDay = new Map<string, number>();
    let earliest: Date | null = null;
    let latest: Date | null = null;

    items.forEach((it) => {
      const d = new Date(it.date);
      if (Number.isNaN(d.getTime())) return;
      const day = startOfDay(d);
      const key = dayKey(day);
      const amount = parseFloat(String(it.price || 0)) || 0;
      spendByDay.set(key, (spendByDay.get(key) || 0) + amount);
      if (!earliest || day < earliest) earliest = day;
      if (!latest || day > latest) latest = day;
    });

    if (!earliest || !latest) {
      return { weeks: [] as DayCell[][], monthMarkers: [] as { week: number; label: string }[], maxAmount: 0 };
    }

    // Anchor the window on the data's own most recent entry, not the real
    // "today" — this app's data can be historical/seed data far in the
    // past, and anchoring to the real date would render an all-empty grid.
    const gridEnd = startOfDay(latest);
    const earliestDay = startOfDay(earliest);

    const cappedStart = new Date(gridEnd);
    cappedStart.setDate(gridEnd.getDate() - (MAX_WEEKS * 7 - 1));
    const rangeStart = earliestDay > cappedStart ? earliestDay : cappedStart;

    const gridStart = new Date(rangeStart);
    gridStart.setDate(gridStart.getDate() - gridStart.getDay());

    const cols: DayCell[][] = [];
    let cursor = new Date(gridStart);
    let max = 0;

    while (cursor <= gridEnd) {
      const col: DayCell[] = [];
      for (let row = 0; row < 7; row++) {
        const d = new Date(cursor);
        d.setDate(cursor.getDate() + row);
        const key = dayKey(d);
        const amount = d > gridEnd || d < earliestDay ? -1 : spendByDay.get(key) || 0;
        if (amount > max) max = amount;
        col.push({ date: d, key, amount });
      }
      cols.push(col);
      cursor.setDate(cursor.getDate() + 7);
    }

    const markers: { week: number; label: string }[] = [];
    let lastMonth = -1;
    cols.forEach((col, wi) => {
      const firstValid = col.find((c) => c.amount >= 0);
      if (!firstValid) return;
      const m = firstValid.date.getMonth();
      if (m !== lastMonth) {
        markers.push({ week: wi, label: MONTH_LABELS[m] });
        lastMonth = m;
      }
    });

    return { weeks: cols, monthMarkers: markers, maxAmount: max };
  }, [items]);

  if (items.length === 0) {
    return (
      <Box>
        <Typography variant="subtitle1">Spend Calendar</Typography>
        <Box className="heatmap-empty">
          <Typography variant="body2" sx={{ color: tokens.textMuted }}>
            No data yet
          </Typography>
        </Box>
      </Box>
    );
  }

  return (
    <Box>
      <Typography variant="subtitle1">Spend Calendar</Typography>
      <Box className="heatmap-scroll">
        <div className="heatmap-inner">
          <div className="heatmap-months" style={{ gridTemplateColumns: `repeat(${weeks.length}, 14px)` }}>
            {weeks.map((_, wi) => {
              const marker = monthMarkers.find((m) => m.week === wi);
              return (
                <span key={wi} className="heatmap-month-label">
                  {marker ? marker.label : ""}
                </span>
              );
            })}
          </div>
          <div className="heatmap-body">
            <div className="heatmap-weekdays">
              {WEEKDAY_LABELS.map((label, i) => (
                <span key={i} className="heatmap-weekday-label">
                  {i % 2 === 1 ? label : ""}
                </span>
              ))}
            </div>
            <div
              className="heatmap-grid"
              style={{ gridTemplateColumns: `repeat(${weeks.length}, 12px)` }}
            >
              {weeks.map((col, wi) => (
                <div key={wi} className="heatmap-col">
                  {col.map((cell) => {
                    if (cell.amount < 0) {
                      return <div key={cell.key} className="heatmap-cell heatmap-cell--void" />;
                    }
                    const level = intensityLevel(cell.amount, maxAmount);
                    const dateLabel = cell.date.toLocaleDateString("en-IN", {
                      month: "short",
                      day: "numeric",
                      year: "numeric",
                    });
                    const title =
                      cell.amount > 0
                        ? `₹${Math.round(cell.amount).toLocaleString("en-IN")} on ${dateLabel}`
                        : `No spend on ${dateLabel}`;
                    return (
                      <div
                        key={cell.key}
                        className="heatmap-cell"
                        title={title}
                        style={{ backgroundColor: LEVEL_COLORS[level] }}
                      />
                    );
                  })}
                </div>
              ))}
            </div>
          </div>
        </div>
      </Box>
    </Box>
  );
};

export default SpendHeatmapCalendar;
